{
  "packet_id": "H6-T01-1",
  "claim_id": "C035",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C035.component",
    "value": "Historical weeks may provide context only when their definitions are comparable.",
    "scope": "Definition comparability is a necessary condition alongside comparable coverage, not a sufficient condition by itself.",
    "provenance": {
      "refs": [
        {
          "source_id": "P019",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P019 supplies both comparability conditions; the component preserves coverage as an additional necessary condition."
    }
  },
  "signal_basis": {
    "component_id": "C035.signal_basis",
    "value": "The booking sequence is examined for repeated delays and other temporal patterns, with historical weeks supplying context only where definitions and coverage are comparable.",
    "scope": "Temporal interpretation of booking observations; historical context remains subject to both comparability conditions.",
    "provenance": {
      "refs": [
        {
          "source_id": "P015",
          "role": "SUPPORT"
        },
        {
          "source_id": "P019",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P015 identifies the temporal patterns sought, and P019 explicitly bounds historical contextual use."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C035.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The supported claim requires no unresolved empirical relation to supply its warrant."
    }
  },
  "rationale": "Comparable definitions are warranted as a necessary condition for interpreting historical observations alongside the current sequence: changes in what events or delays mean could otherwise produce misleading temporal comparisons. The claim preserves comparable coverage as another requirement and does not assert that definition comparability alone establishes usable historical context.",
  "uncertainty": "Whether particular historical weeks satisfy these conditions is not established, but that does not undermine the stated restriction on their use.",
  "anomalies": []
}
